        client ??= createGitLabClient({
            proxy: input.proxy,
            token: input.token,
            apiBaseUrl: input.apiBaseUrl ?? gitlabApiBaseUrl(),
            project: input.project.pathWithNamespace,
            fetch: input.fetch,
        });
